#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Assemble original files, preserve all constants, and disclose partial code."""
from pathlib import Path
from decimal import Decimal, ROUND_HALF_UP
import gzip
import hashlib
import json
import shutil
import subprocess
from fixed_data_generate import listing_records, source_line

ROOT = Path(__file__).resolve().parents[1]


def main():
    results = []
    fixture_maps = []
    native = ['/* SPDX-License-Identifier: MIT',
              ' * Byte-original assembled constants; generated by tools/gimbal_source.py. */']
    for mission, short in [('Luminary099', 'lm'), ('Comanche055', 'cm')]:
        work = ROOT / 'build/gimbal-source' / mission
        work.mkdir(parents=True, exist_ok=True)
        for path in (ROOT / 'build/fixed-data' / mission).glob('*.agc'):
            shutil.copyfile(path, work / path.name)
        original = ROOT.parent / mission / 'GIMBAL_LOCK_AVOIDANCE.agc'
        shutil.copyfile(original, work / original.name)
        assert (work / original.name).read_bytes() == original.read_bytes()
        with (work / 'assembly.lst').open('w') as out:
            subprocess.run([str(ROOT / 'deps/virtualagc/yaYUL/yaYUL'), 'MAIN.agc'],
                           cwd=work, stdout=out, stderr=subprocess.STDOUT, check=True)
        rope = (work / 'MAIN.agc.bin').read_bytes()
        assert rope == (ROOT / 'build/fixed-data' / mission / 'MAIN.agc.bin').read_bytes()
        name = mission + '/' + original.name
        rows = listing_records(work / 'assembly.lst', {original.name: name},
                               {name: original.read_text()}, rope)
        assert {row['line'] for row in rows} == {
            i for i, text in enumerate(original.read_text().splitlines(), 1)
            if source_line(text) is not None}
        fixture_maps.append({'mission': mission, 'rows': rows})
        data = [row for row in rows if row['op'] == '2DEC']
        first = data[0]['physical_fixed_word']
        words = []
        for row in data:
            assert row['physical_fixed_word'] == first + len(words)
            magnitude = int((abs(Decimal(row['arguments'])) * (2 ** 28)).to_integral_value(rounding=ROUND_HALF_UP))
            expected = [magnitude >> 14, magnitude & 0o37777]
            if row['arguments'].startswith('-'):
                expected = [word ^ 0o77777 for word in expected]
            assert row['words'] == expected, row
            words += row['words']
        assert len(words) == (10 if short == 'lm' else 30)
        native += ['static const uint16_t gimbal_' + short + '_words[' + str(len(words)) + ']={' +
                   ','.join('0%06o' % word for word in words) + '};',
                   '#define GIMBAL_' + short.upper() + '_DATA_START ' + str(first) + 'u']
        reached_call = False
        for row in rows:
            if row['op'] == '2DEC':
                row['native_mapping'] = 'complete immutable src/gimbal_data.inc constant, independent Decimal/listing/rope checks'
                row['completion'] = 'complete data'
            elif not row['words']:
                row['native_mapping'] = 'compile-time source placement/alias; actual assembled bank22 retained'
                row['completion'] = 'complete declaration'
            elif not reached_call:
                row['native_mapping'] = 'src/gimbal_stage.c complete entry stage through external DELCOMP call'
                row['completion'] = 'qualified boundary stage'
                if row['op'] == 'DELCOMP':
                    reached_call = True
            else:
                row['native_mapping'] = 'not yet composed/proven; external DELCOMP and CM MXV helpers remain'
                row['completion'] = 'partial/untranslated'
        assert reached_call
        results.append({'source_path': name, 'source_sha256': hashlib.sha256(original.read_bytes()).hexdigest(),
                        'original_bytes': True, 'indentation_repairs': [],
                        'rope_sha256': hashlib.sha256(rope).hexdigest(),
                        'full_file_status': 'partial', 'native_constant_words': len(words),
                        'source_line_and_word_map': rows,
                        'native_source': 'src/gimbal_stage.c', 'native_data': 'src/gimbal_data.inc',
                        'qualified_entry_stage': 'NOGIMLOC/WCALC through actual external DELCOMP entry',
                        'unproved_helpers': ['DELCOMP'] + (['MXV'] if short == 'cm' else []),
                        'later_file_stages_proven': False, 'instruction_decoder': False})
        (ROOT / ('evidence/gimbal-' + short + '-original-assembly.lst.gz')).write_bytes(
            gzip.compress((work / 'assembly.lst').read_bytes(), mtime=0))
    (ROOT / 'build/gimbal-source/maps.json').write_text(json.dumps(fixture_maps, indent=2))
    (ROOT / 'src/gimbal_data.inc').write_text('\n'.join(native) + '\n')
    (ROOT / 'evidence/gimbal-source-audit.json.gz').write_bytes(
        gzip.compress(json.dumps({'schema': 1, 'source_files': results}, indent=2).encode(), mtime=0))
    print('PASS: byte-original LM/CM source; all 40 constant words independently match Decimal, listing, and rope')
    print('PARTIAL: entry stages stop before DELCOMP; later arithmetic, matrices and final NEWANGL continuations remain unproven')


if __name__ == '__main__':
    main()
